:root {
  --ink: #03151c;
  --ink-2: #061f27;
  --deep: #03252c;
  --foam: #edf5ee;
  --muted: #a5bdb9;
  --dim: #6e8e8e;
  --accent: #ff6a4d;
  --accent-bright: #ff896b;
  --aqua: #8ff7e5;
  --gold: #f5c978;
  --line: rgba(221, 245, 236, 0.18);
  --glass: rgba(4, 22, 28, 0.54);
  --display: 'Barlow Condensed', 'Arial Narrow', sans-serif;
  --body: 'Inter', system-ui, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--foam);
  font-family: var(--body);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body {
  overscroll-behavior: none;
  user-select: none;
  -webkit-user-select: none;
}

button {
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

#app {
  position: fixed;
  inset: 0;
  isolation: isolate;
  overflow: hidden;
  background: #04171d;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: crosshair;
}

/* ── Cinematic grade ──────────────────────────────────────────── */
#grade {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  overflow: hidden;
}
.grade-vignette {
  position: absolute;
  inset: -2px;
  background:
    radial-gradient(ellipse at 50% 45%, transparent 38%, rgba(0, 8, 12, 0.16) 70%, rgba(0, 7, 10, 0.72) 120%);
  mix-blend-mode: multiply;
}
.grade-water {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(180deg, rgba(63, 192, 186, 0.19), transparent 26%),
    radial-gradient(ellipse at 50% 0%, rgba(151, 255, 241, 0.12), transparent 54%);
  mix-blend-mode: screen;
  opacity: 1;
  transition: opacity 0.6s ease;
}
.above .grade-water {
  opacity: 0;
}
.grade-grain {
  position: absolute;
  inset: -40%;
  opacity: 0.12;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.55'/%3E%3C/svg%3E");
  background-size: 180px 180px;
  mix-blend-mode: soft-light;
  animation: grainShift 0.8s steps(2) infinite;
}
@keyframes grainShift {
  0% { transform: translate3d(0, 0, 0); }
  25% { transform: translate3d(-2%, 1%, 0); }
  50% { transform: translate3d(1%, -2%, 0); }
  75% { transform: translate3d(2%, 2%, 0); }
  100% { transform: translate3d(-1%, -1%, 0); }
}
.grade-scan {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(180deg, transparent 0, transparent 3px, rgba(0, 0, 0, 0.045) 4px);
  opacity: 0.4;
  mix-blend-mode: multiply;
}

#damage-flash,
#surface-flash {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 7;
  opacity: 0;
}
#damage-flash {
  background: radial-gradient(ellipse at center, transparent 25%, rgba(168, 20, 10, 0.58) 100%);
  transition: opacity 0.3s ease;
}
#surface-flash {
  background: rgba(220, 255, 249, 0.72);
  mix-blend-mode: screen;
}

/* ── Shared type ─────────────────────────────────────────────── */
.eyebrow {
  display: flex;
  align-items: center;
  gap: 12px;
  font-family: var(--body);
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.21em;
  text-transform: uppercase;
  color: var(--muted);
}
.eyebrow > span:first-child {
  color: var(--aqua);
}
.eyebrow-line {
  width: 38px;
  height: 1px;
  background: var(--line);
}
.screen {
  position: absolute;
  inset: 0;
  z-index: 10;
  transition: opacity 0.7s cubic-bezier(0.2, 0.7, 0.2, 1), visibility 0.7s;
}
.screen.hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

/* ── Menu ────────────────────────────────────────────────────── */
.menu {
  display: grid;
  grid-template-rows: auto 1fr auto;
  padding: 28px clamp(22px, 4vw, 64px) 24px;
  background:
    linear-gradient(90deg, rgba(2, 14, 19, 0.92) 0%, rgba(2, 15, 20, 0.62) 34%, rgba(2, 15, 20, 0.03) 67%),
    linear-gradient(0deg, rgba(2, 12, 16, 0.92) 0%, transparent 38%, transparent 82%, rgba(2, 12, 16, 0.5) 100%);
}
.menu::before {
  content: '';
  position: absolute;
  left: clamp(22px, 4vw, 64px);
  top: 92px;
  bottom: 94px;
  width: 1px;
  background: linear-gradient(180deg, transparent, rgba(168, 233, 219, 0.24) 24%, rgba(168, 233, 219, 0.1) 78%, transparent);
  pointer-events: none;
}
.menu-nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--line);
  padding-bottom: 18px;
  position: relative;
  z-index: 2;
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
}
.brand-mark {
  width: 26px;
  height: 26px;
  color: var(--accent);
  display: grid;
  place-items: center;
}
.brand-mark svg { width: 100%; height: 100%; }
.brand-copy {
  display: flex;
  flex-direction: column;
  line-height: 1;
}
.brand-copy strong {
  font-family: var(--display);
  font-weight: 700;
  font-size: 15px;
  letter-spacing: 0.18em;
}
.brand-copy small {
  font-size: 7px;
  color: var(--dim);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  margin-top: 4px;
}
.nav-meta {
  display: flex;
  align-items: center;
  gap: 13px;
  color: var(--muted);
  font-size: 8px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}
.live-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 0 rgba(255, 106, 77, 0.55);
  animation: livePulse 2.2s ease-out infinite;
}
@keyframes livePulse {
  0% { box-shadow: 0 0 0 0 rgba(255, 106, 77, 0.5); }
  75%, 100% { box-shadow: 0 0 0 7px rgba(255, 106, 77, 0); }
}
.nav-divider { width: 1px; height: 12px; background: var(--line); }

.menu-body {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) clamp(220px, 20vw, 294px);
  align-items: end;
  gap: clamp(32px, 6vw, 100px);
  padding: 24px 0 38px clamp(0px, 4.6vw, 76px);
}
.menu-hero {
  align-self: center;
  max-width: 760px;
  position: relative;
  z-index: 2;
  padding-top: 2vh;
}
.menu-hero .eyebrow { margin-bottom: clamp(18px, 3.4vh, 40px); }
.logo {
  display: flex;
  align-items: flex-start;
  line-height: 0.71;
  font-family: var(--display);
  font-weight: 800;
  font-size: clamp(8.8rem, 20.2vw, 21rem);
  letter-spacing: -0.052em;
  color: var(--foam);
  text-transform: uppercase;
  position: relative;
  width: max-content;
  max-width: 100%;
  filter: drop-shadow(0 18px 60px rgba(0, 0, 0, 0.38));
}
.logo-a,
.logo-pex {
  background: linear-gradient(180deg, #fbfffa 2%, #dfece6 45%, #aecac1 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  display: inline-block;
}
.logo-pex {
  margin-left: 0.012em;
}
.logo-tooth {
  width: clamp(22px, 2.9vw, 43px);
  height: clamp(66px, 9vw, 138px);
  color: var(--accent);
  margin-top: 0.03em;
  margin-left: clamp(7px, 1.2vw, 18px);
  transform: rotate(11deg);
  filter: drop-shadow(0 0 22px rgba(255, 84, 52, 0.24));
}
.menu-kicker {
  margin-top: clamp(12px, 2vh, 22px);
  font-family: var(--display);
  font-weight: 600;
  font-size: clamp(0.9rem, 1.55vw, 1.25rem);
  letter-spacing: 0.59em;
  text-transform: uppercase;
  color: var(--accent-bright);
}
.menu-lede {
  margin-top: 18px;
  max-width: 430px;
  font-size: clamp(0.67rem, 0.86vw, 0.82rem);
  line-height: 1.85;
  letter-spacing: 0.015em;
  color: #a9c3bb;
}
.menu-actions {
  margin-top: clamp(22px, 3.4vh, 42px);
  display: flex;
  align-items: center;
  gap: 20px;
}
.btn-primary {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: clamp(28px, 3vw, 49px);
  height: 58px;
  padding: 0 10px 0 26px;
  background: var(--accent);
  color: #130a07;
  text-transform: uppercase;
  font-family: var(--display);
  font-weight: 700;
  font-size: 13px;
  letter-spacing: 0.18em;
  overflow: hidden;
  transition: background 0.25s ease, transform 0.25s ease;
  clip-path: polygon(0 0, calc(100% - 13px) 0, 100% 13px, 100% 100%, 0 100%);
}
.btn-primary::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(110deg, transparent 25%, rgba(255, 255, 255, 0.24) 50%, transparent 72%);
  transform: translateX(-120%);
  transition: transform 0.6s ease;
}
.btn-primary:hover { background: #ff7b5e; transform: translateY(-2px); }
.btn-primary:hover::before { transform: translateX(120%); }
.btn-arrow {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(19, 10, 7, 0.34);
  transition: transform 0.25s ease;
}
.btn-arrow svg { width: 18px; height: 18px; }
.btn-primary:hover .btn-arrow { transform: translateX(3px); }
.btn-ghost {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  height: 58px;
  color: var(--muted);
  font-size: 9px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  transition: color 0.2s ease;
}
.btn-ghost:hover { color: var(--foam); }
.sound-icon {
  display: flex;
  align-items: flex-end;
  gap: 2px;
  height: 13px;
}
.sound-icon i {
  display: block;
  width: 2px;
  background: currentColor;
  animation: soundBar 1.2s ease-in-out infinite alternate;
}
.sound-icon i:nth-child(1) { height: 5px; animation-delay: -0.1s; }
.sound-icon i:nth-child(2) { height: 11px; animation-delay: -0.4s; }
.sound-icon i:nth-child(3) { height: 7px; animation-delay: -0.7s; }
.sound-icon i:nth-child(4) { height: 13px; animation-delay: -0.2s; }
.sound-off .sound-icon i { animation-play-state: paused; height: 2px; }
@keyframes soundBar {
  from { transform: scaleY(0.45); }
  to { transform: scaleY(1); }
}
.menu-tip {
  margin-top: 20px;
  font-size: 8px;
  line-height: 1.6;
  color: var(--dim);
  letter-spacing: 0.07em;
  text-transform: uppercase;
}
.tip-key {
  color: var(--gold);
  font-weight: 600;
  letter-spacing: 0.12em;
  margin-right: 8px;
}

.menu-panel {
  align-self: center;
  padding: 18px 0 0;
  border-top: 1px solid var(--line);
  display: flex;
  flex-direction: column;
  color: #b5ccc5;
  position: relative;
}
.menu-panel::after {
  content: '';
  position: absolute;
  top: -1px;
  right: 0;
  width: 46px;
  height: 1px;
  background: var(--accent);
}
.panel-top {
  display: flex;
  justify-content: space-between;
  font-size: 7px;
  letter-spacing: 0.22em;
  color: var(--dim);
}
.panel-graphic {
  position: relative;
  margin: 20px 0 18px;
  height: clamp(120px, 14vw, 180px);
  color: #8bcac0;
  border-bottom: 1px solid rgba(221, 245, 236, 0.09);
}
.panel-graphic svg {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 100%;
  height: 100%;
  transform: translate(-50%, -50%);
  max-width: 210px;
}
.graphic-readout {
  position: absolute;
  right: 4px;
  bottom: 14px;
  font-size: 6px;
  line-height: 1.7;
  letter-spacing: 0.17em;
  color: var(--dim);
  text-align: right;
}
.graphic-readout b {
  color: var(--aqua);
  font-weight: 500;
  font-size: 9px;
}
.panel-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  padding: 14px 0 16px;
  border-bottom: 1px solid rgba(221, 245, 236, 0.09);
}
.panel-stats div { display: flex; flex-direction: column; gap: 5px; }
.panel-stats span {
  font-size: 6px;
  letter-spacing: 0.2em;
  color: var(--dim);
}
.panel-stats b {
  font-family: var(--display);
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 0.08em;
}
.panel-stats b small { font-size: 9px; color: var(--dim); }
.panel-stats b.accent { color: var(--accent-bright); font-size: 10px; letter-spacing: 0.12em; }
.panel-quote {
  margin-top: 18px;
  font-family: var(--display);
  font-weight: 500;
  font-size: 16px;
  line-height: 1.3;
  letter-spacing: 0.03em;
  color: #d2ded9;
}

.menu-footer {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  border-top: 1px solid var(--line);
  padding-top: 16px;
}
.controls {
  display: flex;
  flex-wrap: wrap;
  gap: clamp(14px, 2.4vw, 36px);
}
.control {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--dim);
  font-size: 7px;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  white-space: nowrap;
}
.control-keys { display: flex; gap: 4px; }
kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  border: 1px solid rgba(207, 236, 226, 0.26);
  border-radius: 2px;
  font-family: var(--body);
  font-size: 7px;
  font-weight: 500;
  letter-spacing: 0.06em;
  color: #c8ddd6;
  background: rgba(8, 28, 34, 0.5);
}
.footer-meta {
  display: flex;
  gap: 26px;
  color: var(--dim);
  font-size: 6px;
  letter-spacing: 0.18em;
  white-space: nowrap;
}

/* ── HUD ──────────────────────────────────────────────────────── */
.hud {
  position: absolute;
  inset: 0;
  z-index: 8;
  pointer-events: none;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.7s ease, visibility 0.7s;
  padding: max(24px, env(safe-area-inset-top)) clamp(20px, 3.2vw, 48px) max(20px, env(safe-area-inset-bottom));
}
.playing .hud {
  opacity: 1;
  visibility: visible;
}
.hud-top {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: start;
  gap: 20px;
}
.hud-label {
  display: block;
  font-size: 7px;
  letter-spacing: 0.24em;
  color: var(--dim);
  margin-bottom: 3px;
}
.hud-score-row {
  display: flex;
  align-items: center;
  gap: 12px;
}
#score {
  font-family: var(--display);
  font-weight: 700;
  font-size: clamp(30px, 3.5vw, 48px);
  line-height: 0.9;
  letter-spacing: 0.02em;
  color: var(--foam);
  text-shadow: 0 2px 20px rgba(0, 0, 0, 0.4);
  font-variant-numeric: tabular-nums;
}
.combo-pill {
  position: relative;
  display: flex;
  align-items: center;
  padding: 4px 8px;
  border: 1px solid rgba(255, 106, 77, 0.45);
  color: var(--accent-bright);
  font-family: var(--display);
  font-weight: 700;
  font-size: 12px;
  letter-spacing: 0.07em;
  opacity: 0;
  transform: translateY(4px);
  transition: opacity 0.2s, transform 0.2s;
  overflow: hidden;
}
.combo-pill.on { opacity: 1; transform: translateY(0); }
.combo-pill i {
  position: absolute;
  left: 0;
  bottom: 0;
  height: 1px;
  width: 100%;
  background: var(--accent);
  transform-origin: left;
}
.hud-sub {
  display: block;
  margin-top: 7px;
  font-size: 6px;
  letter-spacing: 0.2em;
  color: var(--dim);
}

.mission {
  justify-self: center;
  width: min(340px, 30vw);
  text-align: center;
  padding-top: 1px;
}
.mission-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 6.5px;
  letter-spacing: 0.18em;
  color: var(--dim);
}
.mission-eyebrow { color: var(--aqua); }
.mission-title {
  font-family: var(--display);
  font-weight: 600;
  font-size: 15px;
  letter-spacing: 0.22em;
  margin: 7px 0 8px;
  color: #e2eee8;
}
.mission-track {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 4px;
}
.mission-track i {
  height: 2px;
  background: rgba(207, 235, 226, 0.16);
  transition: background 0.4s ease, box-shadow 0.4s ease;
}
.mission-track i.done {
  background: var(--accent);
  box-shadow: 0 0 10px rgba(255, 106, 77, 0.55);
}
.hud-right {
  justify-self: end;
  display: flex;
  gap: 8px;
  pointer-events: auto;
}
.icon-btn {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(207, 235, 226, 0.2);
  background: rgba(3, 20, 25, 0.24);
  backdrop-filter: blur(8px);
  color: #b8d0c9;
  transition: background 0.2s, color 0.2s;
}
.icon-btn:hover { background: rgba(170, 235, 222, 0.12); color: var(--foam); }
.icon-btn svg { width: 17px; height: 17px; }
.icon-btn.muted .sound-wave { display: none; }

.alert {
  position: absolute;
  top: max(112px, calc(env(safe-area-inset-top) + 88px));
  left: 50%;
  transform: translate(-50%, -8px);
  display: flex;
  align-items: center;
  gap: 9px;
  color: #ffb4a1;
  font-size: 7.5px;
  letter-spacing: 0.22em;
  opacity: 0;
  transition: opacity 0.25s, transform 0.25s;
  white-space: nowrap;
  text-shadow: 0 0 16px rgba(160, 10, 0, 0.7);
}
.alert.on { opacity: 1; transform: translate(-50%, 0); }
.alert-icon {
  width: 15px;
  height: 15px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255, 125, 98, 0.7);
  border-radius: 50%;
  font-size: 8px;
  color: var(--accent-bright);
}
.alert-rule { width: 22px; height: 1px; background: rgba(255, 125, 98, 0.5); }

.event-feed {
  position: absolute;
  left: 50%;
  top: 31%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  pointer-events: none;
  width: min(420px, 80vw);
}
.event {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--display);
  font-weight: 600;
  font-size: clamp(14px, 1.5vw, 20px);
  letter-spacing: 0.16em;
  color: var(--foam);
  text-transform: uppercase;
  text-shadow: 0 2px 20px rgba(0, 0, 0, 0.7);
  animation: eventOut 2.1s ease forwards;
}
.event b { color: var(--accent-bright); font-weight: 700; }
.event em { font-family: var(--body); font-style: normal; font-size: 7px; letter-spacing: 0.18em; color: var(--aqua); }
.event.gold { color: var(--gold); }
.event.small { font-size: 10px; letter-spacing: 0.24em; color: var(--muted); }
@keyframes eventOut {
  0% { opacity: 0; transform: translateY(12px) scale(0.96); filter: blur(4px); }
  12% { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
  72% { opacity: 1; }
  100% { opacity: 0; transform: translateY(-16px); }
}

.target-reticle {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 58px;
  height: 58px;
  transform: translate(-50%, -50%) scale(0.82);
  opacity: 0;
  transition: opacity 0.2s, transform 0.2s;
}
.target-reticle.on { opacity: 1; transform: translate(-50%, -50%) scale(1); }
.reticle-ring {
  position: absolute;
  inset: 0;
  border: 1px solid rgba(245, 201, 120, 0.72);
  border-radius: 50%;
  box-shadow: 0 0 16px rgba(245, 201, 120, 0.18), inset 0 0 12px rgba(245, 201, 120, 0.12);
  clip-path: polygon(0 0, 32% 0, 32% 2px, 68% 2px, 68% 0, 100% 0, 100% 32%, calc(100% - 2px) 32%, calc(100% - 2px) 68%, 100% 68%, 100% 100%, 68% 100%, 68% calc(100% - 2px), 32% calc(100% - 2px), 32% 100%, 0 100%, 0 68%, 2px 68%, 2px 32%, 0 32%);
}
.reticle-dot {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--gold);
  transform: translate(-50%, -50%);
}
.reticle-label {
  position: absolute;
  top: calc(100% + 7px);
  left: 50%;
  transform: translateX(-50%);
  font-size: 6px;
  letter-spacing: 0.24em;
  color: var(--gold);
  white-space: nowrap;
}

.hud-left {
  position: absolute;
  left: clamp(20px, 3.2vw, 48px);
  bottom: max(26px, calc(env(safe-area-inset-bottom) + 16px));
  width: clamp(150px, 15vw, 196px);
  display: flex;
  flex-direction: column;
  gap: 13px;
}
.meter-block { opacity: 0.94; }
.meter-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 5px;
  font-size: 6px;
  letter-spacing: 0.19em;
  color: var(--dim);
}
.meter-head b {
  font-family: var(--display);
  font-weight: 600;
  font-size: 10px;
  letter-spacing: 0.08em;
  color: #c0d8d0;
}
.meter {
  height: 2px;
  background: rgba(199, 236, 226, 0.16);
  overflow: hidden;
}
.meter i {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, #7bd9c5, var(--aqua));
  box-shadow: 0 0 8px rgba(143, 247, 229, 0.5);
  transition: width 0.25s ease, background 0.3s;
}
.vitality .meter i { background: linear-gradient(90deg, #f5c978, #ffb066); box-shadow: 0 0 8px rgba(245, 201, 120, 0.35); }
.meter-block.low .meter i { background: var(--accent); box-shadow: 0 0 10px rgba(255, 106, 77, 0.6); }
.depth-readout {
  border-left: 1px solid rgba(174, 233, 221, 0.28);
  padding-left: 11px;
  margin-top: 3px;
}
.depth-label {
  display: block;
  font-size: 6px;
  letter-spacing: 0.2em;
  color: var(--dim);
}
.depth-readout div {
  display: flex;
  align-items: baseline;
  gap: 4px;
  margin: 2px 0 2px;
}
.depth-readout b {
  font-family: var(--display);
  font-size: clamp(25px, 2.8vw, 35px);
  line-height: 0.9;
  font-weight: 600;
  letter-spacing: 0.01em;
  color: #dcebe4;
  font-variant-numeric: tabular-nums;
}
.depth-readout div span { font-size: 7px; color: var(--dim); letter-spacing: 0.1em; }
.zone {
  font-size: 5.5px;
  letter-spacing: 0.22em;
  color: var(--aqua);
}

.hud-bottom-right {
  position: absolute;
  right: clamp(20px, 3.2vw, 48px);
  bottom: max(22px, calc(env(safe-area-inset-bottom) + 12px));
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
}
.speed-readout {
  display: flex;
  align-items: baseline;
  gap: 5px;
  color: #dcebe4;
}
#speed-value {
  font-family: var(--display);
  font-size: 31px;
  line-height: 0.8;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.speed-unit { font-size: 6px; letter-spacing: 0.18em; color: var(--dim); }
.boost-wrap { display: flex; align-items: center; gap: 7px; width: 96px; }
.boost-wrap > span { font-size: 5.5px; letter-spacing: 0.16em; color: var(--dim); }
.boost-track { height: 2px; flex: 1; background: rgba(199, 236, 226, 0.14); }
.boost-track i {
  display: block;
  height: 100%;
  width: 100%;
  background: var(--gold);
  transition: width 0.1s linear;
}
.radar-wrap {
  position: relative;
  width: clamp(104px, 9.8vw, 138px);
  aspect-ratio: 1;
  margin-top: 4px;
}
#radar { width: 100%; height: 100%; display: block; }
.radar-n {
  position: absolute;
  left: 50%;
  top: -3px;
  transform: translateX(-50%);
  font-size: 5px;
  letter-spacing: 0.18em;
  color: var(--muted);
}
.radar-label {
  position: absolute;
  left: 50%;
  bottom: -9px;
  transform: translateX(-50%);
  white-space: nowrap;
  font-size: 5px;
  letter-spacing: 0.18em;
  color: var(--dim);
}

.hud-bottom-center {
  position: absolute;
  left: 50%;
  bottom: max(28px, calc(env(safe-area-inset-bottom) + 16px));
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}
.bite-hint {
  display: flex;
  align-items: center;
  gap: 7px;
  opacity: 0.8;
  transition: opacity 0.3s, transform 0.3s;
}
.bite-hint.ready { opacity: 1; transform: scale(1.08); }
.bite-hint.ready kbd { border-color: rgba(255, 106, 77, 0.6); color: #ffd6cb; }
.bite-hint span { font-size: 6px; letter-spacing: 0.2em; color: var(--dim); }
.control-mini {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 5.5px;
  letter-spacing: 0.15em;
  color: rgba(162, 192, 184, 0.62);
  white-space: nowrap;
  transition: opacity 0.8s ease;
}
.control-mini.fade { opacity: 0; }
.control-mini i { width: 2px; height: 2px; border-radius: 50%; background: rgba(162, 192, 184, 0.5); }

/* ── Touch controls ───────────────────────────────────────────── */
.touch-controls {
  display: none;
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.joystick {
  position: absolute;
  left: max(22px, env(safe-area-inset-left));
  bottom: max(28px, calc(env(safe-area-inset-bottom) + 20px));
  width: 112px;
  height: 112px;
  border-radius: 50%;
  border: 1px solid rgba(196, 237, 228, 0.23);
  background: radial-gradient(circle, rgba(120, 214, 201, 0.08), rgba(2, 16, 21, 0.28) 70%);
  pointer-events: auto;
  touch-action: none;
  backdrop-filter: blur(4px);
}
.joystick::before,
.joystick::after {
  content: '';
  position: absolute;
  background: rgba(196, 237, 228, 0.12);
}
.joystick::before { left: 50%; top: 18%; bottom: 18%; width: 1px; }
.joystick::after { top: 50%; left: 18%; right: 18%; height: 1px; }
.joystick-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  border: 1px solid rgba(198, 247, 236, 0.5);
  background: rgba(92, 201, 186, 0.18);
  transform: translate(-50%, -50%);
  box-shadow: 0 0 22px rgba(94, 224, 202, 0.15);
  transition: transform 0.08s linear;
}
.joystick span {
  position: absolute;
  bottom: -17px;
  width: 100%;
  text-align: center;
  font-size: 5px;
  letter-spacing: 0.18em;
  color: var(--dim);
}
.touch-right {
  position: absolute;
  right: max(18px, env(safe-area-inset-right));
  bottom: max(22px, calc(env(safe-area-inset-bottom) + 14px));
  display: grid;
  grid-template-columns: auto auto;
  grid-template-rows: auto auto;
  align-items: end;
  gap: 10px 12px;
  pointer-events: auto;
}
.touch-btn {
  pointer-events: auto;
  border: 1px solid rgba(206, 243, 234, 0.25);
  background: rgba(3, 23, 29, 0.44);
  backdrop-filter: blur(8px);
  color: #d6e9e3;
  font-family: var(--display);
  font-weight: 600;
  letter-spacing: 0.15em;
  touch-action: none;
  transition: background 0.12s, transform 0.12s;
}
.touch-btn:active { background: rgba(120, 229, 209, 0.22); transform: scale(0.95); }
.vertical-pad {
  grid-column: 2;
  grid-row: 1;
  display: flex;
  flex-direction: column;
  gap: 7px;
}
.touch-btn.small {
  width: 42px;
  height: 36px;
  font-size: 10px;
  color: #a6c8bf;
}
.touch-btn.boost {
  grid-column: 1;
  grid-row: 2;
  width: 62px;
  height: 62px;
  border-radius: 50%;
  font-size: 8px;
  color: var(--gold);
  border-color: rgba(245, 201, 120, 0.35);
}
.touch-btn.bite {
  grid-column: 2;
  grid-row: 2;
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: rgba(255, 106, 77, 0.15);
  border-color: rgba(255, 128, 103, 0.42);
  color: #ffd8ce;
  font-size: 11px;
  position: relative;
}
.touch-btn.bite::after {
  content: '';
  position: absolute;
  inset: 7px;
  border: 1px solid rgba(255, 128, 103, 0.25);
  border-radius: 50%;
}

@media (pointer: coarse), (max-width: 900px) {
  .touch-controls { display: block; }
  .hud-bottom-center { display: none; }
  .control-mini { display: none; }
  #game { cursor: default; }
  .controls .control { display: none; }
  .controls::after {
    content: 'TOUCH CONTROLS · LEFT STICK TO SWIM · HOLD BOOST · TAP BITE';
    font-size: 7px;
    letter-spacing: 0.14em;
    color: var(--dim);
  }
}

/* ── Overlays ─────────────────────────────────────────────────── */
.overlay {
  display: grid;
  place-items: center;
  padding: 24px;
  background:
    radial-gradient(ellipse at 70% 30%, rgba(42, 104, 103, 0.18), transparent 52%),
    linear-gradient(90deg, rgba(2, 12, 16, 0.9), rgba(2, 12, 16, 0.62));
  backdrop-filter: blur(7px);
}
.overlay.hidden { opacity: 0; visibility: hidden; pointer-events: none; }
.overlay-card {
  width: min(520px, 92vw);
  border: 1px solid var(--line);
  background: linear-gradient(145deg, rgba(5, 26, 32, 0.9), rgba(3, 17, 22, 0.94));
  padding: clamp(28px, 4vw, 50px);
  position: relative;
  overflow: hidden;
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.4);
  pointer-events: auto;
}
.overlay-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 40%;
  height: 1px;
  background: var(--accent);
}
.overlay-card h2 {
  margin: 22px 0 12px;
  font-family: var(--display);
  font-weight: 700;
  font-size: clamp(3.6rem, 7vw, 5.6rem);
  line-height: 0.82;
  letter-spacing: 0.01em;
}
.overlay-card h2 em { font-style: normal; color: var(--accent); }
.overlay-card > p {
  max-width: 300px;
  font-size: 10px;
  line-height: 1.7;
  letter-spacing: 0.02em;
  color: var(--muted);
}
.overlay-actions {
  display: flex;
  align-items: center;
  gap: 22px;
  margin-top: 28px;
}
.btn-text {
  font-family: var(--display);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
  border-bottom: 1px solid rgba(180, 217, 207, 0.3);
  padding-bottom: 4px;
  transition: color 0.2s, border-color 0.2s;
}
