.pause-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
  margin-top: 34px;
  padding-top: 18px;
  border-top: 1px solid rgba(221, 245, 236, 0.12);
}
.pause-stats div,
.end-stats div { display: flex; flex-direction: column; gap: 4px; }
.pause-stats span,
.end-stats span { font-size: 6px; letter-spacing: 0.2em; color: var(--dim); }
