#rotate-hint { display: none; }

/* ── Loading ──────────────────────────────────────────────────── */
.loading {
  position: absolute;
  inset: 0;
  z-index: 40;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  background: #03151c;
  transition: opacity 0.8s ease, visibility 0.8s;
}
.loading.done { opacity: 0; visibility: hidden; }
.loading-mark {
  width: 38px;
  height: 38px;
  color: var(--accent);
  animation: markFloat 2s ease-in-out infinite;
}
.loading-mark svg { width: 100%; height: 100%; }
@keyframes markFloat {
  0%, 100% { transform: translateY(0); opacity: 0.7; }
  50% { transform: translateY(-5px); opacity: 1; }
}
.loading-text {
  font-size: 7px;
  letter-spacing: 0.32em;
  color: var(--muted);
}
.loading-track {
  width: 136px;
  height: 1px;
  background: rgba(184, 226, 216, 0.15);
  overflow: hidden;
}
.loading-track i {
  display: block;
  height: 100%;
  width: 45%;
  background: var(--accent);
  animation: loadingSlide 1.1s ease-in-out infinite;
}
@keyframes loadingSlide {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(320%); }
}

