import * as THREE from 'three';

const C = {
  back: new THREE.Color('#5f706d'),
  flank: new THREE.Color('#83908b'),
  belly: new THREE.Color('#e9e4d3'),
  fin: new THREE.Color('#657773'),
  mouth: new THREE.Color('#3d1f20'),
  tooth: new THREE.Color('#f1e8ce'),
  eye: new THREE.Color('#071011'),
};

function smoothstep(a, b, x) {
  const t = THREE.MathUtils.clamp((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

function makeBumpTexture() {
  const size = 256;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  const img = ctx.createImageData(size, size);
  for (let i = 0; i < img.data.length; i += 4) {
    const x = (i / 4) % size;
    const y = Math.floor(i / 4 / size);
    const n = 120 + Math.sin(x * 0.63) * 9 + Math.sin(y * 0.41) * 7 + Math.random() * 38;
    img.data[i] = n;
    img.data[i + 1] = n;
    img.data[i + 2] = n;
    img.data[i + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(5, 5);
  return tex;
}

function buildBody(bump) {
  const rings = [
    [-3.08, 0.025, 0.035, -0.02],
    [-2.9, 0.19, 0.16, -0.04],
    [-2.62, 0.39, 0.32, -0.06],
    [-2.25, 0.57, 0.49, -0.05],
    [-1.75, 0.71, 0.62, -0.03],
    [-1.12, 0.8, 0.71, -0.01],
    [-0.35, 0.81, 0.72, 0],
    [0.45, 0.71, 0.64, 0],
    [1.2, 0.54, 0.51, 0],
    [1.88, 0.35, 0.35, 0],
    [2.42, 0.2, 0.22, 0],
    [2.76, 0.08, 0.1, 0],
    [2.94, 0.016, 0.025, 0],
  ];
  const radial = 22;
  const positions = [];
  const colors = [];
  const uvs = [];
  const indices = [];

  for (let r = 0; r < rings.length; r++) {
    const [z, rx, ry, cy] = rings[r];
    for (let i = 0; i < radial; i++) {
      const a = (i / radial) * Math.PI * 2;
      const x = Math.cos(a) * rx;
      const y = Math.sin(a) * ry + cy;
      // Slight lateral compression around the belly gives the body a more organic section.
      const belly = Math.max(0, -Math.sin(a));
      positions.push(x, y - belly * ry * 0.03, z);
      uvs.push(i / radial, r / (rings.length - 1));
      const vertical = y / Math.max(0.001, ry);
      const t = smoothstep(-0.58, 0.34, vertical);
      const col = C.belly.clone().lerp(C.flank, smoothstep(-0.9, -0.15, vertical));
      col.lerp(C.back, t * t);
      // Subtle mottling and worn skin.
      const mottling = (Math.sin(z * 5.1 + x * 8.4) * 0.5 + 0.5) * 0.03;
      col.offsetHSL(0, 0, mottling - 0.015);
      colors.push(col.r, col.g, col.b);
    }
  }
  for (let r = 0; r < rings.length - 1; r++) {
    for (let i = 0; i < radial; i++) {
      const a = r * radial + i;
      const b = r * radial + ((i + 1) % radial);
      const c = (r + 1) * radial + i;
      const d = (r + 1) * radial + ((i + 1) % radial);
      indices.push(a, c, b, b, c, d);
    }
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  geo.setIndex(indices);
  geo.computeVertexNormals();
  const mat = new THREE.MeshPhysicalMaterial({
    vertexColors: true,
    roughness: 0.42,
    metalness: 0.03,
    clearcoat: 0.65,
    clearcoatRoughness: 0.32,
    bumpMap: bump,
    bumpScale: 0.018,
    envMapIntensity: 0.85,
  });
  return new THREE.Mesh(geo, mat);
}

function finGeometry(points, thickness = 0.09, bevel = 0.035) {
  const shape = new THREE.Shape();
  shape.moveTo(points[0][0], points[0][1]);
  for (let i = 1; i < points.length; i++) shape.lineTo(points[i][0], points[i][1]);
  shape.closePath();
  const geo = new THREE.ExtrudeGeometry(shape, {
    depth: thickness,
    bevelEnabled: true,
    bevelSegments: 2,
    bevelSize: bevel,
    bevelThickness: bevel,
    curveSegments: 8,
  });
  geo.translate(0, 0, -thickness * 0.5);
  // Shape X becomes world Z, so fins sit in the vertical fore-aft plane.
  geo.rotateY(-Math.PI / 2);
  return geo;
}

function curvedFinGeometry(points, thickness = 0.08) {
  const shape = new THREE.Shape();
  shape.moveTo(points[0][0], points[0][1]);
  for (let i = 1; i < points.length; i += 1) {
    const p = points[i];
    const prev = points[i - 1];
    if (p.length > 2) {
      shape.quadraticCurveTo(p[0], p[1], p[2], p[3]);
    } else {
      shape.lineTo(p[0], p[1]);
    }
  }
  shape.closePath();
  const geo = new THREE.ExtrudeGeometry(shape, {
    depth: thickness,
    bevelEnabled: true,
    bevelSegments: 2,
    bevelSize: 0.028,
    bevelThickness: 0.028,
    curveSegments: 10,
  });
  geo.translate(0, 0, -thickness * 0.5);
  geo.rotateY(-Math.PI / 2);
  return geo;
}

function makeWingMesh(side, mat) {
  // A broad, swept pectoral fin built in the X/Y plane then laid nearly flat.
  const pts = [
    [0, 0],
    [1.38, -0.52],
    [2.18, -1.02],
    [2.2, -1.36],
    [1.72, -1.4],
    [0.48, -0.52],
  ];
  const shape = new THREE.Shape();
  shape.moveTo(pts[0][0], pts[0][1]);
  for (let i = 1; i < pts.length; i++) shape.lineTo(pts[i][0], pts[i][1]);
  shape.closePath();
  const geo = new THREE.ExtrudeGeometry(shape, {
    depth: 0.08,
    bevelEnabled: true,
    bevelSize: 0.025,
    bevelThickness: 0.025,
    bevelSegments: 2,
  });
  geo.translate(0, 0, -0.04);
  geo.rotateX(-Math.PI / 2);
  geo.rotateZ(side > 0 ? 0 : Math.PI);
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.set(side * 0.58, -0.25, -1.05);
  mesh.rotation.z = side * -0.18;
  return mesh;
}

function tube(points, radius, color, opacity = 1) {
  const curve = new THREE.CatmullRomCurve3(points.map(p => new THREE.Vector3(...p)));
  const geo = new THREE.TubeGeometry(curve, 12, radius, 4, false);
  const mat = new THREE.MeshBasicMaterial({ color, transparent: opacity < 1, opacity });
  return new THREE.Mesh(geo, mat);
}

function buildJawParts(material, toothMat) {
  const jaw = new THREE.Group();
  const mouthMat = new THREE.MeshPhysicalMaterial({
    color: C.mouth,
    roughness: 0.72,
    clearcoat: 0.15,
  });
  const interior = new THREE.Mesh(new THREE.SphereGeometry(1, 18, 10), mouthMat);
  interior.scale.set(0.52, 0.2, 0.56);
  interior.position.set(0, -0.34, -2.47);
  jaw.add(interior);

  const lower = new THREE.Mesh(new THREE.SphereGeometry(1, 16, 8), material);
  lower.scale.set(0.53, 0.18, 0.46);
  lower.position.set(0, -0.45, -2.48);
  jaw.add(lower);

  const teethGroup = new THREE.Group();
  for (let i = 0; i < 9; i++) {
    const side = i < 5 ? -1 : 1;
    const k = i < 5 ? i : i - 5;
    const x = side * (0.1 + k * 0.1);
    const z = -2.82 + Math.abs(x) * 0.38 + k * 0.018;
    const tooth = new THREE.Mesh(new THREE.ConeGeometry(0.035, 0.17, 5), toothMat);
    tooth.position.set(x, -0.42, z);
    tooth.rotation.x = Math.PI;
    tooth.rotation.z = -x * 0.7;
    teethGroup.add(tooth);
  }
  jaw.add(teethGroup);

  jaw.position.set(0, 0, 0);
  return jaw;
}

export function createShark() {
  const group = new THREE.Group();
  group.name = 'Great White';
  const model = new THREE.Group();
  group.add(model);

  const bump = makeBumpTexture();
  const body = buildBody(bump);
  model.add(body);

  const finMat = new THREE.MeshPhysicalMaterial({
    color: C.fin,
    roughness: 0.48,
    metalness: 0.02,
    clearcoat: 0.4,
    clearcoatRoughness: 0.3,
    bumpMap: bump,
    bumpScale: 0.012,
    envMapIntensity: 0.75,
  });
  const darkFinMat = new THREE.MeshPhysicalMaterial({
    color: new THREE.Color('#536663'),
    roughness: 0.55,
    clearcoat: 0.25,
    envMapIntensity: 0.6,
  });
  const toothMat = new THREE.MeshPhysicalMaterial({
    color: C.tooth,
    roughness: 0.36,
    clearcoat: 0.25,
    emissive: new THREE.Color('#2b2413'),
    emissiveIntensity: 0.05,
  });
  const eyeMat = new THREE.MeshPhysicalMaterial({
    color: C.eye,
    roughness: 0.08,
    metalness: 0.2,
    clearcoat: 1,
    clearcoatRoughness: 0.02,
  });

  // Primary dorsal fin.
  const dorsalPts = [
    [0.42, 0.35],
    [0.22, 1.4],
    [-0.03, 1.72],
    [-0.35, 1.46],
    [-0.78, 0.58],
  ];
  const dorsal = new THREE.Mesh(curvedFinGeometry(dorsalPts, 0.1), finMat);
  dorsal.position.set(0, 0.27, 0.22);
  model.add(dorsal);

  // Second, smaller dorsal.
  const dorsal2 = new THREE.Mesh(finGeometry([
    [0.3, -0.14],
    [0.25, 0.2],
    [0.55, 0.38],
    [0.64, 0.08],
  ], 0.06), darkFinMat);
  dorsal2.position.set(0, 0.14, 1.72);
  model.add(dorsal2);

  // Pectoral fins.
  const leftFin = makeWingMesh(-1, finMat);
  const rightFin = makeWingMesh(1, finMat);
  leftFin.rotation.x = -0.12;
  rightFin.rotation.x = -0.12;
  model.add(leftFin, rightFin);

  // Pelvic fins.
  for (const side of [-1, 1]) {
    const pelvic = new THREE.Mesh(finGeometry([
      [0.22, -0.08],
      [0.38, -0.5],
      [0.7, -0.45],
      [0.76, -0.12],
    ], 0.055), darkFinMat);
    pelvic.scale.x = side;
    pelvic.position.set(side * 0.3, -0.2, 1.22);
    model.add(pelvic);
  }

  // Tail stock and caudal fin.
  const tail = new THREE.Group();
  tail.position.set(0, 0, 2.56);
  const tailPts = [
    [0, 0],
    [0.34, 0.3],
    [0.82, 1.16],
    [1.1, 1.1],
    [0.58, 0.28],
    [0.72, -0.05],
    [1.16, -0.68],
    [1.08, -1.02],
    [0.62, -0.82],
    [0.08, -0.18],
  ];
  const tailFin = new THREE.Mesh(curvedFinGeometry(tailPts, 0.09), finMat);
  tailFin.position.set(0, 0, 0);
  tail.add(tailFin);
  model.add(tail);

  // Mouth and jaw.
  const jaw = buildJawParts(finMat, toothMat);
  model.add(jaw);

  // Upper teeth follow the edge of the snout.
  const upperTeeth = new THREE.Group();
  for (let i = 0; i < 10; i++) {
    const side = i < 5 ? -1 : 1;
    const k = i < 5 ? i : i - 5;
    const x = side * (0.12 + k * 0.083);
    const z = -2.9 + Math.abs(x) * 0.4 + k * 0.018;
    const tooth = new THREE.Mesh(new THREE.ConeGeometry(0.032, 0.16, 5), toothMat);
    tooth.position.set(x, -0.17, z);
    tooth.rotation.x = Math.PI;
    tooth.rotation.z = x * 0.55;
    upperTeeth.add(tooth);
  }
  model.add(upperTeeth);

  // Eyes.
  for (const side of [-1, 1]) {
    const socket = new THREE.Mesh(new THREE.SphereGeometry(0.125, 14, 10), darkFinMat);
    socket.scale.set(1, 0.85, 0.9);
    socket.position.set(side * 0.53, 0.16, -2.08);
    model.add(socket);
    const eye = new THREE.Mesh(new THREE.SphereGeometry(0.088, 16, 12), eyeMat);
    eye.position.set(side * 0.585, 0.17, -2.05);
    model.add(eye);
    const glint = new THREE.Mesh(
      new THREE.SphereGeometry(0.02, 6, 5),
      new THREE.MeshBasicMaterial({ color: '#d8f4ef' })
    );
    glint.position.set(side * 0.63, 0.215, -2.03);
    model.add(glint);
  }

  // Gill slits.
  for (const side of [-1, 1]) {
    for (let i = 0; i < 5; i++) {
      const z = -1.34 + i * 0.17;
      const gill = tube([
        [side * 0.72, 0.3, z],
        [side * 0.795, 0.04, z - 0.035],
        [side * 0.735, -0.24, z - 0.05],
      ], 0.011, '#263634', 0.86);
      model.add(gill);
    }
  }

  // Nostrils.
  for (const side of [-1, 1]) {
    const nostril = new THREE.Mesh(
      new THREE.SphereGeometry(0.026, 7, 5),
      new THREE.MeshBasicMaterial({ color: '#1b2928' })
    );
    nostril.position.set(side * 0.2, -0.08, -2.86);
    nostril.scale.set(1, 0.7, 0.5);
    model.add(nostril);
  }

  // Old scars give the animal a history.
  model.add(tube([
    [0.72, 0.45, 0.1],
    [0.76, 0.3, 0.4],
    [0.66, 0.1, 0.7],
  ], 0.012, '#c2cdc4', 0.42));
  model.add(tube([
    [-0.7, 0.36, 0.7],
    [-0.75, 0.18, 0.92],
  ], 0.009, '#bdc9c1', 0.34));

  // A few remora-like pilot fish following the apex predator.
  const escorts = [];
  const escortMat = new THREE.MeshStandardMaterial({ color: '#829ca0', roughness: 0.6 });
  for (let i = 0; i < 3; i++) {
    const fish = new THREE.Mesh(new THREE.SphereGeometry(0.07, 6, 5), escortMat);
    fish.scale.set(0.45, 0.7, 2.2);
    fish.userData = { phase: i * 2.1, offset: new THREE.Vector3(1.2 + i * 0.25, 0.2 - i * 0.14, 0.8 + i * 0.35) };
    escorts.push(fish);
    model.add(fish);
  }

  const pivotMouth = new THREE.Vector3(0, -0.28, -2.15);
  jaw.position.copy(pivotMouth);
  jaw.children.forEach(child => child.position.sub(pivotMouth));

  const state = {
    jawOpen: 0,
    bite: 0,
    tailPhase: 0,
    roll: 0,
    speed: 0,
  };

  function update(dt, time, speed, turn) {
    state.speed += (speed - state.speed) * Math.min(1, dt * 4);
    state.tailPhase += dt * (2.7 + speed * 0.36);
    const wag = 0.18 + Math.min(0.24, speed * 0.012);
    tail.rotation.y = Math.sin(state.tailPhase) * wag;
    tail.rotation.z = Math.sin(state.tailPhase * 0.5) * 0.03;
    leftFin.rotation.z = -0.18 - Math.sin(state.tailPhase * 0.5 + 0.8) * 0.045;
    rightFin.rotation.z = 0.18 + Math.sin(state.tailPhase * 0.5) * 0.045;
    jaw.rotation.x = state.jawOpen * 0.62;
    jaw.rotation.z = Math.sin(state.tailPhase * 0.3) * 0.008;
    model.position.y = Math.sin(time * 1.65) * 0.035;
    model.rotation.z = Math.sin(time * 0.9) * 0.012 - turn * 0.09;
    model.rotation.x = Math.sin(time * 0.7) * 0.008;

    state.jawOpen += ((state.bite > 0 ? 1 : 0) - state.jawOpen) * Math.min(1, dt * 15);
    state.bite = Math.max(0, state.bite - dt);

    for (const fish of escorts) {
      const p = fish.userData;
      const t = time * 0.9 + p.phase;
      fish.position.copy(p.offset).add(new THREE.Vector3(
        Math.sin(t) * 0.25,
        Math.sin(t * 1.7) * 0.08,
        Math.cos(t) * 0.3
      ));
      fish.rotation.y = Math.PI / 2 + Math.sin(t) * 0.2;
      fish.rotation.z = Math.sin(t * 1.4) * 0.15;
    }
  }

  function bite() {
    state.bite = 0.42;
  }

  function setRoll(r) {
    state.roll = r;
  }

  group.userData = { model, tail, jaw, bite, update, setRoll };
  return group;
}

export class OceanAudio {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.enabled = true;
    this.started = false;
    this.shipGain = null;
    this.underwaterGain = null;
    this.drone = [];
    this.noiseBuffer = null;
    this.lastWhale = 0;
    this.lastPing = 0;
  }

  init() {
    if (this.started) {
      if (this.ctx?.state === 'suspended') this.ctx.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    this.started = true;
    this.master = this.ctx.createGain();
    this.master.gain.value = this.enabled ? 0.7 : 0;
    const compressor = this.ctx.createDynamicsCompressor();
    compressor.threshold.value = -18;
    compressor.knee.value = 18;
    compressor.ratio.value = 5;
    compressor.attack.value = 0.01;
    compressor.release.value = 0.35;
    this.master.connect(compressor).connect(this.ctx.destination);

    this.noiseBuffer = this.createNoise(4);

    // Deep-water pressure and current.
    this.underwaterGain = this.ctx.createGain();
    this.underwaterGain.gain.value = 0.14;
    this.underwaterGain.connect(this.master);
    const low = this.loopNoise(0.12);
    const lowFilter = this.ctx.createBiquadFilter();
    lowFilter.type = 'lowpass';
    lowFilter.frequency.value = 210;
    lowFilter.Q.value = 0.4;
    low.connect(lowFilter).connect(this.underwaterGain);

    const current = this.loopNoise(0.06);
    const currentFilter = this.ctx.createBiquadFilter();
    currentFilter.type = 'bandpass';
    currentFilter.frequency.value = 620;
    currentFilter.Q.value = 0.35;
    current.connect(currentFilter).connect(this.underwaterGain);

    // A pair of clean sub drones.
    for (const [freq, gainValue] of [[43, 0.035], [64.5, 0.018], [86, 0.009]]) {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'sine';
      osc.frequency.value = freq;
      gain.gain.value = gainValue;
      const lfo = this.ctx.createOscillator();
      const lfoGain = this.ctx.createGain();
      lfo.frequency.value = 0.045 + Math.random() * 0.03;
      lfoGain.gain.value = gainValue * 0.38;
      lfo.connect(lfoGain).connect(gain.gain);
      osc.connect(gain).connect(this.master);
      osc.start();
      lfo.start();
      this.drone.push(osc, lfo);
    }

    // Engine rumble for nearby ships.
    this.shipGain = this.ctx.createGain();
    this.shipGain.gain.value = 0;
    this.shipGain.connect(this.master);
    const engine = this.ctx.createOscillator();
    engine.type = 'sawtooth';
    engine.frequency.value = 36;
    const engineFilter = this.ctx.createBiquadFilter();
    engineFilter.type = 'lowpass';
    engineFilter.frequency.value = 105;
    const engineAmp = this.ctx.createGain();
    engineAmp.gain.value = 0.2;
    engine.connect(engineFilter).connect(engineAmp).connect(this.shipGain);
    engine.start();
    this.engineOsc = engine;

    const hum = this.ctx.createOscillator();
    hum.type = 'sine';
    hum.frequency.value = 72;
    const humGain = this.ctx.createGain();
    humGain.gain.value = 0.06;
    hum.connect(humGain).connect(this.shipGain);
    hum.start();
  }

  createNoise(seconds) {
    const len = Math.floor(this.ctx.sampleRate * seconds);
    const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      last = (last + 0.02 * white) / 1.02;
      data[i] = last * 3.2 + white * 0.5;
    }
    return buffer;
  }

  loopNoise(rate) {
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;
    src.playbackRate.value = rate;
    src.start();
    return src;
  }

  setEnabled(enabled) {
    this.enabled = enabled;
    if (this.master) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.setTargetAtTime(enabled ? 0.7 : 0, this.ctx.currentTime, 0.08);
    }
  }

  setUnderwater(amount) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    this.underwaterGain.gain.setTargetAtTime(0.12 + 0.08 * amount, t, 0.35);
    this.shipGain.gain.setTargetAtTime(0.04 + 0.32 * (1 - amount), t, 0.2);
  }

  setShipProximity(value) {
    if (!this.ctx || !this.shipGain) return;
    this.shipGain.gain.setTargetAtTime(0.02 + Math.pow(value, 1.6) * 0.16, this.ctx.currentTime, 0.2);
    if (this.engineOsc) this.engineOsc.frequency.setTargetAtTime(34 + value * 10, this.ctx.currentTime, 0.3);
  }

  tone(freq, dur, type = 'sine', vol = 0.1, when = 0, slideTo = null) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + when;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (slideTo) osc.frequency.exponentialRampToValueAtTime(slideTo, t + dur);
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(vol, t + 0.018);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(gain).connect(this.master);
    osc.start(t);
    osc.stop(t + dur + 0.05);
  }

  noiseBurst(dur, filterType, freq, vol, q = 1, when = 0) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + when;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.playbackRate.value = 1.4;
    const filter = this.ctx.createBiquadFilter();
    filter.type = filterType;
    filter.frequency.value = freq;
    filter.Q.value = q;
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(vol, t + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(filter).connect(gain).connect(this.master);
    src.start(t, Math.random() * 2);
    src.stop(t + dur + 0.05);
  }

  bite() {
    this.noiseBurst(0.18, 'bandpass', 760, 0.5, 0.7);
    this.tone(66, 0.26, 'sine', 0.27, 0.01, 38);
    this.tone(145, 0.08, 'triangle', 0.1, 0.01, 90);
  }

  crunch() {
    this.noiseBurst(0.1, 'bandpass', 1300, 0.26, 1.4, 0.02);
    this.noiseBurst(0.16, 'lowpass', 420, 0.24, 0.5, 0.06);
    this.tone(88, 0.12, 'triangle', 0.14, 0.02, 61);
  }

  boost() {
    this.noiseBurst(0.55, 'bandpass', 420, 0.19, 0.5);
    this.noiseBurst(0.8, 'lowpass', 220, 0.16, 0.4, 0.04);
  }

  splash() {
    this.noiseBurst(0.75, 'highpass', 430, 0.42, 0.7);
    this.noiseBurst(0.5, 'bandpass', 1100, 0.28, 0.5, 0.02);
    this.tone(58, 0.55, 'sine', 0.18, 0, 34);
  }

  seal() {
    this.tone(510, 0.15, 'triangle', 0.11, 0, 690);
    this.tone(770, 0.11, 'sine', 0.07, 0.08, 560);
  }

  sonar() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    if (now - this.lastPing < 8) return;
    this.lastPing = now;
    this.tone(980, 1.4, 'sine', 0.055, 0, 720);
    this.tone(1470, 0.9, 'sine', 0.018, 0.03, 1220);
  }

  whale() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    if (now - this.lastWhale < 24) return;
    this.lastWhale = now;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 380;
    osc.type = 'sine';
    const t = now + 0.1;
    osc.frequency.setValueAtTime(92, t);
    osc.frequency.linearRampToValueAtTime(142, t + 1.4);
    osc.frequency.linearRampToValueAtTime(106, t + 3.2);
    osc.frequency.linearRampToValueAtTime(72, t + 5.6);
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.linearRampToValueAtTime(0.045, t + 1.2);
    gain.gain.linearRampToValueAtTime(0.0001, t + 6);
    osc.connect(filter).connect(gain).connect(this.master);
    osc.start(t);
    osc.stop(t + 6.2);
  }

  event(type) {
    if (!this.ctx) return;
    if (type === 'seal') {
      this.tone(220, 0.5, 'sine', 0.06, 0, 440);
      this.tone(440, 0.35, 'sine', 0.045, 0.08, 660);
    } else if (type === 'danger') {
      this.tone(140, 0.22, 'square', 0.035);
      this.tone(140, 0.22, 'square', 0.035, 0.25);
    } else if (type === 'complete') {
      [261, 329, 392, 523].forEach((f, i) => this.tone(f, 0.8, 'sine', 0.055, i * 0.12));
    } else if (type === 'ui') {
      this.tone(680, 0.06, 'sine', 0.035, 0, 540);
    }
  }
}

import * as THREE from 'three';

const rand = (a, b) => a + Math.random() * (b - a);
const clamp = THREE.MathUtils.clamp;
const TAU = Math.PI * 2;

/* ──────────────────────────────────────────────────────────────
   Small procedural texture helpers
   ────────────────────────────────────────────────────────────── */
function canvasTexture(w, h, draw) {
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  const ctx = c.getContext('2d');
  draw(ctx, w, h);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function softCircleTexture(inner = 'rgba(255,255,255,1)', outer = 'rgba(255,255,255,0)') {
  return canvasTexture(64, 64, (ctx, w, h) => {
    const g = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
    g.addColorStop(0, inner);
    g.addColorStop(0.32, inner);
    g.addColorStop(1, outer);
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  });
}

function ringTexture() {
  return canvasTexture(128, 128, (ctx, w, h) => {
    ctx.translate(w / 2, h / 2);
    ctx.strokeStyle = 'rgba(255,255,255,.9)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(0, 0, 48, 0, TAU);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(255,255,255,.28)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(0, 0, 35, 0, TAU);
    ctx.stroke();
    for (let i = 0; i < 4; i++) {
      ctx.save();
      ctx.rotate((i * TAU) / 4);
      ctx.fillStyle = 'rgba(255,255,255,.85)';
      ctx.fillRect(-1.5, -57, 3, 9);
      ctx.restore();
    }
  });
}

function beamTexture() {
  return canvasTexture(128, 512, (ctx, w, h) => {
    const grad = ctx.createLinearGradient(0, 0, 0, h);
    grad.addColorStop(0, 'rgba(206,255,244,.58)');
    grad.addColorStop(0.4, 'rgba(155,235,219,.17)');
    grad.addColorStop(1, 'rgba(120,220,205,0)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);
    const side = ctx.createLinearGradient(0, 0, w, 0);
    side.addColorStop(0, 'rgba(0,0,0,1)');
    side.addColorStop(0.25, 'rgba(0,0,0,0)');
    side.addColorStop(0.75, 'rgba(0,0,0,0)');
    side.addColorStop(1, 'rgba(0,0,0,1)');
    ctx.globalCompositeOperation = 'destination-out';
    ctx.fillStyle = side;
    ctx.fillRect(0, 0, w, h);
  });
}

function foamTexture() {
  return canvasTexture(256, 512, (ctx, w, h) => {
    ctx.clearRect(0, 0, w, h);
    for (let i = 0; i < 1200; i++) {
      const x = Math.random() * w;
      const y = Math.random() * h;
      const alpha = Math.random() * 0.38;
      const r = Math.random() * 3.2 + 0.5;
      ctx.fillStyle = `rgba(228,255,248,${alpha})`;
      ctx.beginPath();
      ctx.ellipse(x, y, r * 1.8, r * 0.55, Math.random() * Math.PI, 0, TAU);
      ctx.fill();
    }
  });
}

function makeEnvironment() {
  return canvasTexture(1024, 512, (ctx, w, h) => {
    const sky = ctx.createLinearGradient(0, 0, 0, h * 0.56);
    sky.addColorStop(0, '#1b5b74');
    sky.addColorStop(0.48, '#78b3bd');
    sky.addColorStop(0.72, '#efc7a8');
    sky.addColorStop(1, '#f8ddbf');
    ctx.fillStyle = sky;
    ctx.fillRect(0, 0, w, h * 0.56);
    const sea = ctx.createLinearGradient(0, h * 0.56, 0, h);
    sea.addColorStop(0, '#1e5961');
    sea.addColorStop(1, '#031b22');
    ctx.fillStyle = sea;
    ctx.fillRect(0, h * 0.56, w, h * 0.44);
    const sun = ctx.createRadialGradient(w * 0.77, h * 0.39, 0, w * 0.77, h * 0.39, 105);
    sun.addColorStop(0, 'rgba(255,250,222,1)');
    sun.addColorStop(0.15, 'rgba(255,228,178,.9)');
    sun.addColorStop(0.5, 'rgba(255,190,130,.25)');
    sun.addColorStop(1, 'rgba(255,180,120,0)');
    ctx.fillStyle = sun;
    ctx.fillRect(0, 0, w, h);
  });
}

/* ──────────────────────────────────────────────────────────────
   Sky
   ────────────────────────────────────────────────────────────── */
function createSky() {
  const geo = new THREE.SphereGeometry(780, 40, 22);
  const mat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
    uniforms: {
      uTime: { value: 0 },
      uSun: { value: new THREE.Vector3(-0.66, 0.4, -0.64).normalize() },
      uTop: { value: new THREE.Color('#276b89') },
      uMid: { value: new THREE.Color('#8bb8c1') },
      uHorizon: { value: new THREE.Color('#f6c8a2') },
      uSunColor: { value: new THREE.Color('#fff1ce') },
    },
    vertexShader: /* glsl */ `
      varying vec3 vDir;
      void main() {
        vDir = normalize(position);
        vec4 mv = modelViewMatrix * vec4(position, 1.0);
        gl_Position = projectionMatrix * mv;
      }
    `,
    fragmentShader: /* glsl */ `
      uniform float uTime;
      uniform vec3 uSun;
      uniform vec3 uTop;
      uniform vec3 uMid;
      uniform vec3 uHorizon;
      uniform vec3 uSunColor;
      varying vec3 vDir;

      float hash(vec2 p) {
        return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
      }
      float noise(vec2 p) {
        vec2 i = floor(p);
        vec2 f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
                   mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y);
      }
      float fbm(vec2 p) {
        float v = 0.0;
        float a = 0.55;
        for (int i = 0; i < 4; i++) {
          v += a * noise(p);
          p *= 2.03;
          a *= 0.5;
        }
        return v;
      }

      void main() {
        float h = normalize(vDir).y;
        vec3 col = mix(uHorizon, uMid, smoothstep(-0.02, 0.28, h));
        col = mix(col, uTop, smoothstep(0.2, 0.82, h));

        float sunDot = max(dot(normalize(vDir), uSun), 0.0);
        float glow = pow(sunDot, 12.0) * 0.32 + pow(sunDot, 140.0) * 0.7;
        col += uSunColor * glow;
        float disk = smoothstep(0.9992, 0.9997, sunDot);
        col += uSunColor * disk * 2.6;

        vec3 dir = normalize(vDir);
        vec2 cloudUv = dir.xz / max(dir.y + 0.32, 0.08) * 1.25;
        float cloud = fbm(cloudUv * 1.25 + vec2(uTime * 0.004, uTime * 0.0015));
        cloud = smoothstep(0.53, 0.8, cloud) * smoothstep(0.02, 0.24, h) * (1.0 - smoothstep(0.62, 0.9, h));
        vec3 cloudCol = mix(vec3(0.97, 0.84, 0.72), vec3(0.98, 0.94, 0.86), h);
        col = mix(col, cloudCol, cloud * 0.62);

        float haze = 1.0 - smoothstep(0.0, 0.085, abs(h + 0.005));
        col = mix(col, vec3(0.95, 0.82, 0.7), haze * 0.45);
        gl_FragColor = vec4(col, 1.0);
      }
    `,
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.renderOrder = -20;
  mesh.frustumCulled = false;
  return mesh;
}

/* ──────────────────────────────────────────────────────────────
   Ocean surface
   ────────────────────────────────────────────────────────────── */
function createOcean() {
  const geo = new THREE.PlaneGeometry(1500, 1500, 190, 190);
  geo.rotateX(-Math.PI / 2);
  const mat = new THREE.ShaderMaterial({
    side: THREE.DoubleSide,
    transparent: false,
    uniforms: {
      uTime: { value: 0 },
      uSun: { value: new THREE.Vector3(-0.66, 0.4, -0.64).normalize() },
      uShallow: { value: new THREE.Color('#2b8c8d') },
      uDeep: { value: new THREE.Color('#052c39') },
      uSky: { value: new THREE.Color('#a9cfd2') },
      uSunColor: { value: new THREE.Color('#ffedc5') },
      uFogColor: { value: new THREE.Color('#073743') },
      uFogDensity: { value: 0.012 },
    },
    vertexShader: /* glsl */ `
      uniform float uTime;
      varying vec3 vWorld;
      varying vec3 vNormalW;
      varying float vHeight;

      float wave(vec2 p) {
        float t = uTime;
        float w = sin(p.x * 0.23 + t * 0.72) * 0.42;
        w += sin(p.y * 0.31 - t * 0.54) * 0.33;
        w += sin((p.x + p.y) * 0.15 + t * 0.4) * 0.66;
        w += sin((p.x * 0.7 - p.y * 0.5) * 0.13 - t * 0.86) * 0.44;
        w += sin(p.x * 0.95 + p.y * 0.82 + t * 1.22) * 0.11;
        w += sin(p.x * 1.65 - p.y * 1.2 - t * 1.7) * 0.045;
        return w;
      }

      void main() {
        vec3 p = position;
        float h = wave(p.xz);
        p.y += h;
        float e = 1.25;
        float hx = wave(p.xz + vec2(e, 0.0));
        float hz = wave(p.xz + vec2(0.0, e));
        vec3 n = normalize(vec3(h - hx, e, h - hz));
        vHeight = h;
        vec4 world = modelMatrix * vec4(p, 1.0);
        vWorld = world.xyz;
        vNormalW = normalize(mat3(modelMatrix) * n);
        gl_Position = projectionMatrix * viewMatrix * world;
      }
    `,
    fragmentShader: /* glsl */ `
      uniform float uTime;
      uniform vec3 uSun;
      uniform vec3 uShallow;
      uniform vec3 uDeep;
      uniform vec3 uSky;
      uniform vec3 uSunColor;
      uniform vec3 uFogColor;
      uniform float uFogDensity;
      varying vec3 vWorld;
      varying vec3 vNormalW;
      varying float vHeight;

      float hash(vec2 p) {
        return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
      }
      float noise(vec2 p) {
        vec2 i = floor(p);
        vec2 f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
                   mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y);
      }

      void main() {
        vec3 toCam = normalize(cameraPosition - vWorld);
        vec3 n = normalize(vNormalW);
        float dist = distance(cameraPosition, vWorld);
        float fog = 1.0 - exp(-pow(dist * uFogDensity, 2.0));
        bool above = cameraPosition.y > 0.12;

        if (above) {
          float fres = pow(1.0 - max(dot(n, toCam), 0.0), 2.6);
          vec3 col = mix(uDeep, uSky, fres * 0.82);
          col = mix(col, uShallow, smoothstep(0.38, 0.95, fres) * 0.32);
          vec3 refl = reflect(-toCam, n);
          float spec = pow(max(dot(refl, uSun), 0.0), 240.0);
          float glint = pow(max(dot(refl, uSun), 0.0), 18.0) * 0.12;
          col += uSunColor * (spec * 5.2 + glint);
          float foamNoise = noise(vWorld.xz * 0.45 + uTime * 0.05);
          float crest = smoothstep(1.2, 1.62, vHeight + foamNoise * 0.22);
          vec3 foam = vec3(0.74, 0.9, 0.86);
          col = mix(col, foam, crest * 0.38);
          float shimmer = noise(vWorld.xz * 1.4 - uTime * 0.14);
          col += uSky * shimmer * 0.018;
          col = mix(col, uFogColor, fog * 0.94);
          gl_FragColor = vec4(col, 1.0);
        } else {
          float upness = abs(toCam.y);
          float window = smoothstep(0.18, 0.95, upness);
          vec3 deepCol = vec3(0.016, 0.115, 0.145);
          vec3 windowCol = vec3(0.34, 0.72, 0.72);
          vec3 col = mix(deepCol, windowCol, window * 0.82);
          float ripple = sin(vWorld.x * 0.75 + uTime * 0.7 + sin(vWorld.z * 0.45)) *
                         sin(vWorld.z * 0.96 - uTime * 0.52);
          ripple = ripple * 0.5 + 0.5;
          float caustic = smoothstep(0.58, 0.94, ripple);
          col += vec3(0.24, 0.62, 0.55) * caustic * window * 0.36;
          col += uSunColor * pow(max(toCam.y, 0.0), 5.0) * 0.04;
          float rim = pow(1.0 - upness, 4.0);
          col = mix(col, vec3(0.05, 0.28, 0.31), rim * 0.42);
          col = mix(col, uFogColor, fog * 0.96);
          gl_FragColor = vec4(col, 1.0);
        }
      }
    `,
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.y = 0;
  mesh.renderOrder = -1;
  mesh.frustumCulled = false;
  return mesh;
}

/* ──────────────────────────────────────────────────────────────
   Sea floor, rocks and kelp
   ────────────────────────────────────────────────────────────── */
function createSeafloor() {
  const group = new THREE.Group();
  const geo = new THREE.PlaneGeometry(900, 900, 110, 110);
  geo.rotateX(-Math.PI / 2);
  const pos = geo.attributes.position;
  const colors = [];
  const colorA = new THREE.Color('#1b3534');
  const colorB = new THREE.Color('#3e493c');
  const colorC = new THREE.Color('#665846');
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i);
    const z = pos.getZ(i);
    const y = -62
      + Math.sin(x * 0.055) * 2.2
      + Math.cos(z * 0.041) * 1.8
      + Math.sin((x + z) * 0.023) * 3.2
      + Math.sin(x * 0.16 + z * 0.11) * 0.55;
    pos.setY(i, y);
    const n = (Math.sin(x * 0.14 + z * 0.08) * 0.5 + 0.5) * 0.65
      + (Math.sin(x * 0.4 - z * 0.27) * 0.5 + 0.5) * 0.35;
    const col = colorA.clone().lerp(colorB, n).lerp(colorC, Math.max(0, n - 0.68) * 1.5);
    colors.push(col.r, col.g, col.b);
  }
  geo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  geo.computeVertexNormals();
  const mat = new THREE.MeshStandardMaterial({
    vertexColors: true,
    roughness: 1,
    metalness: 0,
    color: '#a0a392',
  });
  const floor = new THREE.Mesh(geo, mat);
  floor.position.y = 0;
  group.add(floor);

  // Soft moving caustic light on the sand.
  const causticMat = new THREE.ShaderMaterial({
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    uniforms: { uTime: { value: 0 } },
    vertexShader: /* glsl */ `
      varying vec2 vUv;
      varying vec3 vWorld;
      void main() {
        vUv = uv;
        vec4 world = modelMatrix * vec4(position, 1.0);
        vWorld = world.xyz;
        gl_Position = projectionMatrix * viewMatrix * world;
      }
    `,
    fragmentShader: /* glsl */ `
      uniform float uTime;
      varying vec2 vUv;
      varying vec3 vWorld;
      void main() {
        float c1 = sin(vWorld.x * 0.5 + uTime * 0.75 + sin(vWorld.z * 0.4)) * sin(vWorld.z * 0.55 - uTime * 0.5);
        float c2 = sin((vWorld.x + vWorld.z) * 0.34 - uTime * 0.62 + sin(vWorld.x * 0.2)) * sin((vWorld.z - vWorld.x) * 0.37 + uTime * 0.45);
        float c = smoothstep(0.12, 0.92, c1 * 0.5 + 0.5) * 0.55 + smoothstep(0.4, 0.95, c2 * 0.5 + 0.5) * 0.45;
        float edge = smoothstep(0.0, 0.15, vUv.x) * smoothstep(1.0, 0.85, vUv.x) * smoothstep(0.0, 0.15, vUv.y) * smoothstep(1.0, 0.85, vUv.y);
        gl_FragColor = vec4(vec3(0.35, 0.85, 0.74) * c, c * edge * 0.22);
      }
    `,
  });
  const caustic = new THREE.Mesh(new THREE.PlaneGeometry(800, 800, 1, 1), causticMat);
  caustic.rotation.x = -Math.PI / 2;
  caustic.position.y = -58.5;
  group.add(caustic);

  // Rocks.
  const rockGeo = new THREE.IcosahedronGeometry(1, 1);
  const rockMat = new THREE.MeshStandardMaterial({
    color: '#263d3a',
    roughness: 0.94,
    flatShading: true,
  });
  const rocks = new THREE.InstancedMesh(rockGeo, rockMat, 36);
  const dummy = new THREE.Object3D();
  for (let i = 0; i < 36; i++) {
    const angle = Math.random() * TAU;
    const radius = 18 + Math.random() * 220;
    const s = rand(1.8, 8.5);
    dummy.position.set(Math.cos(angle) * radius, -61 + s * 0.28, Math.sin(angle) * radius);
    dummy.rotation.set(rand(0, TAU), rand(0, TAU), rand(0, TAU));
    dummy.scale.set(s * rand(0.7, 1.4), s * rand(0.45, 1.0), s * rand(0.7, 1.35));
    dummy.updateMatrix();
    rocks.setMatrixAt(i, dummy.matrix);
  }
  group.add(rocks);

  // Kelp forest. A single merged mesh with a custom swaying shader.
  const positions = [];
  const colors = [];
  const phases = [];
  const indices = [];
  let vertexOffset = 0;
  const baseColor = new THREE.Color('#0b3b35');
  const tipColor = new THREE.Color('#4f9d72');
  for (let k = 0; k < 64; k++) {
    const angle = Math.random() * TAU;
    const radius = 18 + Math.random() * 210;
    const bx = Math.cos(angle) * radius;
    const bz = Math.sin(angle) * radius;
    const height = rand(5, 18);
    const width = rand(0.16, 0.48);
    const segments = 9;
    const phase = Math.random() * TAU;
    for (let s = 0; s <= segments; s++) {
      const t = s / segments;
      const w = width * (1 - t * 0.82) * (0.6 + Math.sin(t * 7 + phase) * 0.12);
      const y = -60 + t * height;
      positions.push(bx - w, y, bz);
      positions.push(bx + w, y, bz);
      const c = baseColor.clone().lerp(tipColor, Math.pow(t, 0.7));
      colors.push(c.r, c.g, c.b, c.r, c.g, c.b);
      phases.push(phase, phase);
    }
    for (let s = 0; s < segments; s++) {
      const a = vertexOffset + s * 2;
      indices.push(a, a + 2, a + 1, a + 1, a + 2, a + 3);
    }
    vertexOffset += (segments + 1) * 2;
  }
  const kelpGeo = new THREE.BufferGeometry();
  kelpGeo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  kelpGeo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  kelpGeo.setAttribute('aPhase', new THREE.Float32BufferAttribute(phases, 1));
  kelpGeo.setIndex(indices);
  const kelpMat = new THREE.ShaderMaterial({
    side: THREE.DoubleSide,
    transparent: true,
    depthWrite: false,
    vertexColors: true,
    uniforms: { uTime: { value: 0 } },
    vertexShader: /* glsl */ `
      uniform float uTime;
      attribute float aPhase;
      varying vec3 vColor;
      varying float vY;
      void main() {
        vColor = color;
        vY = position.y;
        float height = clamp((position.y + 60.0) / 16.0, 0.0, 1.0);
        float sway = sin(uTime * 0.55 + aPhase + position.y * 0.11) * pow(height, 1.6);
        vec3 p = position;
        p.x += sway * 0.62;
        p.z += cos(uTime * 0.42 + aPhase * 0.7 + position.y * 0.09) * pow(height, 1.6) * 0.36;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0);
      }
    `,
    fragmentShader: /* glsl */ `
      varying vec3 vColor;
      varying float vY;
      void main() {
        float fade = smoothstep(-60.0, -46.0, vY);
        gl_FragColor = vec4(vColor * (0.72 + fade * 0.33), 0.82);
      }
    `,
  });
  const kelp = new THREE.Mesh(kelpGeo, kelpMat);
  group.add(kelp);

  group.userData.causticMat = causticMat;
  group.userData.kelpMat = kelpMat;
  return group;
}

/* ──────────────────────────────────────────────────────────────
   Light shafts, marine snow, bubbles, blood, splash
   ────────────────────────────────────────────────────────────── */
function createShafts() {
  const group = new THREE.Group();
  const tex = beamTexture();
  const mat = new THREE.MeshBasicMaterial({
    map: tex,
    transparent: true,
    opacity: 0.13,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide,
    color: '#bff8e8',
  });
  const shafts = [];
  for (let i = 0; i < 15; i++) {
    const mesh = new THREE.Mesh(new THREE.PlaneGeometry(rand(12, 34), rand(58, 86)), mat.clone());
    const angle = Math.random() * TAU;
    const radius = Math.random() * 150;
    mesh.position.set(Math.cos(angle) * radius, -35, Math.sin(angle) * radius);
    mesh.rotation.y = Math.random() * TAU;
    mesh.rotation.z = rand(-0.18, 0.18);
    mesh.material.opacity = rand(0.035, 0.12);
    mesh.userData.baseOpacity = mesh.material.opacity;
    mesh.userData.phase = Math.random() * TAU;
    group.add(mesh);
    shafts.push(mesh);
  }
  group.userData.shafts = shafts;
  return group;
}

function createMarineSnow() {
  const count = 950;
  const positions = new Float32Array(count * 3);
  const speeds = new Float32Array(count);
  for (let i = 0; i < count; i++) {
    positions[i * 3] = rand(-140, 140);
    positions[i * 3 + 1] = rand(-62, -1);
    positions[i * 3 + 2] = rand(-140, 140);
    speeds[i] = rand(0.05, 0.3);
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  const mat = new THREE.PointsMaterial({
    size: 0.19,
    map: softCircleTexture(),
    color: '#b6e8df',
    transparent: true,
    opacity: 0.42,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    sizeAttenuation: true,
  });
  const points = new THREE.Points(geo, mat);
  points.userData.speeds = speeds;
  return points;
}

function createParticlePool(count, color, size, texture, blending = THREE.AdditiveBlending) {
  const positions = new Float32Array(count * 3);
  const life = new Float32Array(count);
  const vel = new Float32Array(count * 3);
  for (let i = 0; i < count; i++) positions[i * 3 + 1] = -999;
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  const mat = new THREE.PointsMaterial({
    size,
    map: texture,
    color,
    transparent: true,
    opacity: 0.7,
    depthWrite: false,
    blending,
    sizeAttenuation: true,
  });
  const points = new THREE.Points(geo, mat);
  points.frustumCulled = false;
  points.userData = { positions, life, vel, cursor: 0, count };
  return points;
}

class Particles {
  constructor(scene) {
    this.tex = softCircleTexture();
    this.bubbles = createParticlePool(220, '#c8fff5', 0.18, this.tex);
    this.splash = createParticlePool(180, '#eafffb', 0.34, this.tex);
    this.blood = createParticlePool(130, '#9c1c12', 0.34, this.tex, THREE.NormalBlending);
    this.snow = createMarineSnow();
    scene.add(this.bubbles, this.splash, this.blood, this.snow);

    this.cloudTex = canvasTexture(128, 128, (ctx, w, h) => {
      const g = ctx.createRadialGradient(w / 2, h / 2, 2, w / 2, h / 2, w / 2);
      g.addColorStop(0, 'rgba(115,11,7,.9)');
      g.addColorStop(0.45, 'rgba(79,8,4,.42)');
      g.addColorStop(1, 'rgba(35,3,2,0)');
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, w, h);
    });
    this.clouds = [];
    for (let i = 0; i < 5; i++) {
      const mat = new THREE.SpriteMaterial({
        map: this.cloudTex,
        transparent: true,
        opacity: 0,
        depthWrite: false,
        color: '#ff5b40',
      });
      const sp = new THREE.Sprite(mat);
      sp.scale.set(1, 1, 1);
      sp.visible = false;
      scene.add(sp);
      this.clouds.push({ sprite: sp, life: 0, maxLife: 1 });
    }

    this.ringTex = ringTexture();
    this.rings = [];
    for (let i = 0; i < 4; i++) {
      const mat = new THREE.MeshBasicMaterial({
        map: this.ringTex,
        transparent: true,
        opacity: 0,
        depthWrite: false,
        side: THREE.DoubleSide,
        color: '#d9fff6',
        blending: THREE.AdditiveBlending,
      });
      const mesh = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), mat);
      mesh.rotation.x = -Math.PI / 2;
      mesh.visible = false;
      scene.add(mesh);
      this.rings.push({ mesh, life: 0, maxLife: 1 });
    }
    this.bubbleClock = 0;
  }

  spawn(kind, pos, count, speed = 1) {
    const pool = kind === 'bubble' ? this.bubbles : kind === 'splash' ? this.splash : this.blood;
    const d = pool.userData;
    for (let n = 0; n < count; n++) {
      const i = d.cursor;
      d.cursor = (d.cursor + 1) % d.count;
      d.life[i] = rand(0.5, 1.8) * (kind === 'splash' ? 1.15 : 1);
      d.positions[i * 3] = pos.x + rand(-0.55, 0.55);
      d.positions[i * 3 + 1] = pos.y + rand(-0.4, 0.4);
      d.positions[i * 3 + 2] = pos.z + rand(-0.55, 0.55);
      if (kind === 'bubble') {
        d.vel[i * 3] = rand(-0.25, 0.25);
        d.vel[i * 3 + 1] = rand(0.7, 1.9) * speed;
        d.vel[i * 3 + 2] = rand(-0.25, 0.25);
      } else if (kind === 'splash') {
        d.vel[i * 3] = rand(-2.4, 2.4) * speed;
        d.vel[i * 3 + 1] = rand(2.5, 7.5) * speed;
        d.vel[i * 3 + 2] = rand(-2.4, 2.4) * speed;
      } else {
        d.vel[i * 3] = rand(-1.2, 1.2);
        d.vel[i * 3 + 1] = rand(-0.6, 0.9);
        d.vel[i * 3 + 2] = rand(-1.2, 1.2);
      }
    }
    pool.geometry.attributes.position.needsUpdate = true;
  }

  bloodCloud(pos) {
    const cloud = this.clouds.find(c => c.life <= 0) || this.clouds[0];
    cloud.life = 1.7;
    cloud.maxLife = 1.7;
    cloud.sprite.position.copy(pos);
    cloud.sprite.scale.setScalar(1);
    cloud.sprite.visible = true;
  }

  surfaceRing(pos, scale = 1) {
    const ring = this.rings.find(r => r.life <= 0) || this.rings[0];
    ring.life = 1.5;
    ring.maxLife = 1.5;
    ring.mesh.position.set(pos.x, 0.1, pos.z);
    ring.mesh.scale.setScalar(scale * 2);
    ring.mesh.visible = true;
  }

  update(dt, time, camera, shark, speed) {
    for (const [pool, isSplash] of [[this.bubbles, false], [this.splash, true], [this.blood, false]]) {
      const d = pool.userData;
      for (let i = 0; i < d.count; i++) {
        if (d.life[i] <= 0) continue;
        d.life[i] -= dt;
        if (d.life[i] <= 0) {
          d.positions[i * 3 + 1] = -999;
          continue;
        }
        d.positions[i * 3] += d.vel[i * 3] * dt;
        d.positions[i * 3 + 1] += d.vel[i * 3 + 1] * dt;
        d.positions[i * 3 + 2] += d.vel[i * 3 + 2] * dt;
        if (pool === this.bubbles) {
          d.vel[i * 3] += Math.sin(time * 2 + i) * 0.08 * dt;
        }
        if (isSplash) d.vel[i * 3 + 1] -= 9.8 * dt;
        else if (pool === this.blood) {
          d.vel[i * 3] *= 0.98;
          d.vel[i * 3 + 2] *= 0.98;
        }
      }
      pool.geometry.attributes.position.needsUpdate = true;
    }
    for (const c of this.clouds) {
      if (c.life <= 0) { c.sprite.visible = false; continue; }
      c.life -= dt;
      const t = 1 - c.life / c.maxLife;
      c.sprite.scale.setScalar(1.5 + t * 8);
      c.sprite.material.opacity = (1 - t) * 0.65;
      if (c.life <= 0) c.sprite.visible = false;
    }
    for (const r of this.rings) {
      if (r.life <= 0) { r.mesh.visible = false; continue; }
      r.life -= dt;
      const t = 1 - r.life / r.maxLife;
      r.mesh.scale.setScalar(2 + t * 26);
      r.mesh.material.opacity = (1 - t) * 0.5;
      if (r.life <= 0) r.mesh.visible = false;
    }
    const sp = this.snow.userData.speeds;
    const arr = this.snow.geometry.attributes.position.array;
    for (let i = 0; i < sp.length; i++) {
      arr[i * 3 + 1] -= sp[i] * dt;
      arr[i * 3] += Math.sin(time * 0.2 + i) * 0.02 * dt;
      if (arr[i * 3 + 1] < -64) arr[i * 3 + 1] = -1;
    }
    this.snow.geometry.attributes.position.needsUpdate = true;
    if (this.snow.position.y > 0) this.snow.position.y = 0;

    if (shark && speed > 2) {
      this.bubbleClock -= dt;
      if (this.bubbleClock <= 0) {
        this.bubbleClock = 0.18 + Math.random() * 0.3;
        this.spawn('bubble', shark, Math.random() > 0.65 ? 3 : 1, 0.7 + speed * 0.025);
      }
    }
  }
}

/* ──────────────────────────────────────────────────────────────
   Fish schools
   ────────────────────────────────────────────────────────────── */
function fishBodyGeometry() {
  const geo = new THREE.SphereGeometry(0.26, 7, 5);
  geo.scale(0.42, 0.62, 1.7);
  return geo;
}

function fishTailGeometry() {
  const geo = new THREE.BufferGeometry();
  const verts = new Float32Array([
    0, 0, 0.1, 0, 0.22, 0.45, 0, -0.22, 0.45,
  ]);
  geo.setAttribute('position', new THREE.BufferAttribute(verts, 3));
  geo.computeVertexNormals();
  return geo;
}

class FishSchool {
  constructor(scene, center, count, tint) {
    this.center = center.clone();
    this.anchor = center.clone();
    this.count = count;
    this.fish = [];
    this.body = new THREE.InstancedMesh(
      fishBodyGeometry(),
      new THREE.MeshStandardMaterial({
        color: '#8fb3b4',
        roughness: 0.38,
        metalness: 0.35,
        envMapIntensity: 1.2,
      }),
      count
    );
    this.tail = new THREE.InstancedMesh(
      fishTailGeometry(),
      new THREE.MeshBasicMaterial({ color: '#92b6b7', side: THREE.DoubleSide, transparent: true, opacity: 0.8 }),
      count
    );
    this.body.frustumCulled = false;
    this.tail.frustumCulled = false;
    const palette = [tint, '#a2bdba', '#73999e', '#b8c9c3'];
    for (let i = 0; i < count; i++) {
      const f = {
        pos: new THREE.Vector3(
          center.x + rand(-9, 9),
          center.y + rand(-3.2, 3.2),
          center.z + rand(-9, 9)
        ),
        vel: new THREE.Vector3(rand(-0.2, 0.2), 0, rand(-0.2, 0.2)),
        phase: Math.random() * TAU,
        rate: rand(0.5, 1.2),
        active: true,
        respawn: 0,
      };
      this.fish.push(f);
      this.body.setColorAt(i, new THREE.Color(palette[Math.floor(Math.random() * palette.length)]));
      this.tail.setColorAt(i, new THREE.Color(palette[Math.floor(Math.random() * palette.length)]));
    }
    this.body.instanceColor.needsUpdate = true;
    this.tail.instanceColor.needsUpdate = true;
    this.dummy = new THREE.Object3D();
    this.wander = Math.random() * TAU;
    scene.add(this.body, this.tail);
  }

  update(dt, time, shark) {
    this.center.x = this.anchor.x + Math.sin(time * 0.11 + this.wander) * 22;
    this.center.z = this.anchor.z + Math.cos(time * 0.09 + this.wander) * 22;
    this.center.y = this.anchor.y + Math.sin(time * 0.3 + this.wander) * 1.8;
    const sharkDist = shark.distanceTo(this.center);
    const escape = sharkDist < 20;
    for (let i = 0; i < this.count; i++) {
      const f = this.fish[i];
      if (!f.active) {
        f.respawn -= dt;
        if (f.respawn <= 0) {
          f.active = true;
          f.pos.set(this.center.x + rand(-7, 7), this.center.y + rand(-2, 2), this.center.z + rand(-7, 7));
          f.vel.set(0, 0, 0);
        }
        this.dummy.position.copy(f.pos);
        this.dummy.scale.setScalar(0.001);
        this.dummy.updateMatrix();
        this.body.setMatrixAt(i, this.dummy.matrix);
        this.tail.setMatrixAt(i, this.dummy.matrix);
        continue;
      }
      const orbit = time * f.rate + f.phase;
      const target = new THREE.Vector3(
        this.center.x + Math.cos(orbit) * 7 + Math.sin(orbit * 2.1) * 2.3,
        this.center.y + Math.sin(orbit * 0.8) * 2.2,
        this.center.z + Math.sin(orbit) * 7 + Math.cos(orbit * 1.7) * 2.1
      );
      const desired = target.sub(f.pos);
      if (escape) {
        const away = f.pos.clone().sub(shark).normalize();
        f.vel.addScaledVector(away, dt * 22);
        f.vel.x += Math.sin(time * 4 + f.phase) * dt * 7;
        f.vel.z += Math.cos(time * 3.2 + f.phase) * dt * 7;
      } else {
        f.vel.addScaledVector(desired, dt * 0.55);
      }
      f.vel.multiplyScalar(0.965);
      const maxSpeed = escape ? 11 : 3.6;
      if (f.vel.length() > maxSpeed) f.vel.setLength(maxSpeed);
      f.pos.addScaledVector(f.vel, dt);
      const dir = f.vel.lengthSq() > 0.0001 ? f.vel.clone().normalize() : new THREE.Vector3(0, 0, 1);
      this.dummy.position.copy(f.pos);
      this.dummy.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, -1), dir);
      const s = 0.9 + Math.sin(f.phase) * 0.12;
      this.dummy.scale.setScalar(s);
      this.dummy.updateMatrix();
      this.body.setMatrixAt(i, this.dummy.matrix);
      const tailPos = f.pos.clone().addScaledVector(dir, -0.38);
      this.dummy.position.copy(tailPos);
      this.dummy.updateMatrix();
      this.tail.setMatrixAt(i, this.dummy.matrix);
    }
    this.body.instanceMatrix.needsUpdate = true;
    this.tail.instanceMatrix.needsUpdate = true;
  }

  eat(pos, forward, radius) {
    let eaten = 0;
    for (let i = 0; i < this.count && eaten < 3; i++) {
      const f = this.fish[i];
      if (!f.active) continue;
      const d = f.pos.clone().sub(pos);
      if (d.length() < radius && d.normalize().dot(forward) > 0.12) {
        f.active = false;
        f.respawn = rand(14, 24);
        eaten++;
      }
    }
    return eaten;
  }
}

