    e.stopPropagation();
    onDown();
  });
  const release = (e) => {
    e.preventDefault();
    e.stopPropagation();
    onUp();
  };
  button.addEventListener('pointerup', release);
  button.addEventListener('pointercancel', release);
  button.addEventListener('pointerleave', (e) => {
    if (e.buttons === 0) onUp();
  });
}

