43:     [-3.24, 0.016, 0.022, -0.02],
44:     [-3.02, 0.12, 0.1, -0.035],
45:     [-2.78, 0.3, 0.25, -0.05],
46:     [-2.48, 0.48, 0.4, -0.06],
47:     [-2.18, 0.61, 0.52, -0.05],
48:     [-1.75, 0.71, 0.62, -0.03],
49:     [-1.12, 0.8, 0.71, -0.01],
50:     [-0.35, 0.81, 0.72, 0],
51:     [0.45, 0.71, 0.64, 0],
52:     [1.2, 0.54, 0.51, 0],
53:     [1.88, 0.35, 0.35, 0],
54:     [2.42, 0.2, 0.22, 0],
55:     [2.76, 0.08, 0.1, 0],
56:     [2.94, 0.016, 0.025, 0],
57:   ];
58:   const radial = 22;
59:   const positions = [];
60:   const colors = [];
61:   const uvs = [];
62:   const indices = [];
63: 
64:   for (let r = 0; r < rings.length; r++) {
65:     const [z, rx, ry, cy] = rings[r];
66:     for (let i = 0; i < radial; i++) {
67:       const a = (i / radial) * Math.PI * 2;
68:       const x = Math.cos(a) * rx;
69:       const y = Math.sin(a) * ry + cy;
70:       // Slight lateral compression around the belly gives the body a more organic section.
71:       const belly = Math.max(0, -Math.sin(a));
72:       positions.push(x, y - belly * ry * 0.03, z);
73:       uvs.push(i / radial, r / (rings.length - 1));
74:       const vertical = y / Math.max(0.001, ry);
75:       const t = smoothstep(-0.82, -0.02, vertical);
76:       const col = C.belly.clone().lerp(C.flank, smoothstep(-0.96, -0.3, vertical));
77:       col.lerp(C.back, t * t);
78:       // Subtle mottling and worn skin.
79:       const mottling = (Math.sin(z * 5.1 + x * 8.4) * 0.5 + 0.5) * 0.03;
80:       col.offsetHSL(0, 0, mottling - 0.015);
81:       colors.push(col.r, col.g, col.b);
82:     }
83:   }
84:   for (let r = 0; r < rings.length - 1; r++) {
85:     for (let i = 0; i < radial; i++) {
86:       const a = r * radial + i;
87:       const b = r * radial + ((i + 1) % radial);
88:       const c = (r + 1) * radial + i;
89:       const d = (r + 1) * radial + ((i + 1) % radial);
90:       indices.push(a, b, c, b, d, c);
91:     }
92:   }
93:   const geo = new THREE.BufferGeometry();
94:   geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
95:   geo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
96:   geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
97:   geo.setIndex(indices);
98:   geo.computeVertexNormals();
99:   const mat = new THREE.MeshPhysicalMaterial({
100:     vertexColors: true,
101:     roughness: 0.42,
102:     metalness: 0.03,
103:     clearcoat: 0.65,
104:     clearcoatRoughness: 0.32,
105:     bumpMap: bump,
106:     bumpScale: 0.018,
107:     envMapIntensity: 0.85,
108:   });
109:   return new THREE.Mesh(geo, mat);
110: }
