112: function finGeometry(points, thickness = 0.09, bevel = 0.035) {
113:   const shape = new THREE.Shape();
114:   shape.moveTo(points[0][0], points[0][1]);
115:   for (let i = 1; i < points.length; i++) shape.lineTo(points[i][0], points[i][1]);
116:   shape.closePath();
117:   const geo = new THREE.ExtrudeGeometry(shape, {
118:     depth: thickness,
119:     bevelEnabled: true,
120:     bevelSegments: 2,
121:     bevelSize: bevel,
122:     bevelThickness: bevel,
123:     curveSegments: 8,
124:   });
125:   geo.translate(0, 0, -thickness * 0.5);
126:   // Shape X becomes world Z, so fins sit in the vertical fore-aft plane.
127:   geo.rotateY(-Math.PI / 2);
128:   return geo;
129: }
