131: function curvedFinGeometry(points, thickness = 0.08) {
132:   const shape = new THREE.Shape();
133:   shape.moveTo(points[0][0], points[0][1]);
134:   for (let i = 1; i < points.length; i += 1) {
135:     const p = points[i];
136:     const prev = points[i - 1];
137:     if (p.length > 2) {
138:       shape.quadraticCurveTo(p[0], p[1], p[2], p[3]);
139:     } else {
140:       shape.lineTo(p[0], p[1]);
141:     }
142:   }
143:   shape.closePath();
144:   const geo = new THREE.ExtrudeGeometry(shape, {
145:     depth: thickness,
146:     bevelEnabled: true,
147:     bevelSegments: 2,
148:     bevelSize: 0.028,
149:     bevelThickness: 0.028,
150:     curveSegments: 10,
151:   });
152:   geo.translate(0, 0, -thickness * 0.5);
153:   geo.rotateY(-Math.PI / 2);
154:   return geo;
155: }
