157: function makeWingMesh(side, mat) {
158:   // A broad, swept pectoral fin built in the X/Y plane then laid nearly flat.
159:   const pts = [
160:     [0, 0],
161:     [1.38, -0.52],
162:     [2.18, -1.02],
163:     [2.2, -1.36],
164:     [1.72, -1.4],
165:     [0.48, -0.52],
166:   ];
167:   const shape = new THREE.Shape();
168:   shape.moveTo(pts[0][0], pts[0][1]);
169:   for (let i = 1; i < pts.length; i++) shape.lineTo(pts[i][0], pts[i][1]);
170:   shape.closePath();
171:   const geo = new THREE.ExtrudeGeometry(shape, {
172:     depth: 0.08,
173:     bevelEnabled: true,
174:     bevelSize: 0.025,
175:     bevelThickness: 0.025,
176:     bevelSegments: 2,
177:   });
178:   geo.translate(0, 0, -0.04);
179:   geo.rotateX(-Math.PI / 2);
180:   geo.rotateZ(side > 0 ? 0 : Math.PI);
181:   const mesh = new THREE.Mesh(geo, mat);
182:   mesh.position.set(side * 0.58, -0.25, -1.05);
183:   mesh.rotation.z = side * -0.18;
184:   return mesh;
