187: function tube(points, radius, color, opacity = 1) {
188:   const curve = new THREE.CatmullRomCurve3(points.map(p => new THREE.Vector3(...p)));
189:   const geo = new THREE.TubeGeometry(curve, 12, radius, 4, false);
190:   const mat = new THREE.MeshBasicMaterial({ color, transparent: opacity < 1, opacity });
191:   return new THREE.Mesh(geo, mat);
