202:   // The jaw mechanism hides inside the snout while the mouth is closed.
203:   const interior = new THREE.Mesh(new THREE.SphereGeometry(1, 20, 12), mouthMat);
204:   interior.scale.set(0.24, 0.045, 0.14);
