208:   const lower = new THREE.Mesh(new THREE.SphereGeometry(1, 16, 8), material);
209:   lower.scale.set(0.27, 0.035, 0.16);
210:   lower.position.set(0, -0.39, -2.16);
211:   jaw.add(lower);
