213:   const teethGroup = new THREE.Group();
214:   for (let i = 0; i < 8; i++) {
215:     const side = i < 4 ? -1 : 1;
216:     const k = i < 4 ? i : i - 4;
217:     const x = side * (0.035 + k * 0.055);
218:     const z = -2.48 + Math.abs(x) * 0.34 + k * 0.012;
