    this.center.z = this.anchor.z + Math.cos(time * 0.09 + this.wander) * 22;
    this.center.y = this.anchor.y + Math.sin(time * 0.3 + this.wander) * 1.8;
    const sharkDist = shark.distanceTo(this.center);
    const escape = sharkDist < 20;
    for (let i = 0; i < this.count; i++) {
      const f = this.fish[i];
      if (!f.active) {
        f.respawn -= dt;
        if (f.respawn <= 0) {
          f.active = true;
          f.pos.set(this.center.x + rand(-7, 7), this.center.y + rand(-2, 2), this.center.z + rand(-7, 7));
          f.vel.set(0, 0, 0);
