/* ── Cinematic grade ──────────────────────────────────────────── */
#grade {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  overflow: hidden;
}
.grade-vignette {
  position: absolute;
  inset: -2px;
  background:
    radial-gradient(ellipse at 50% 45%, transparent 38%, rgba(0, 8, 12, 0.16) 70%, rgba(0, 7, 10, 0.72) 120%);
  mix-blend-mode: multiply;
}
.grade-water {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(180deg, rgba(63, 192, 186, 0.19), transparent 26%),
    radial-gradient(ellipse at 50% 0%, rgba(151, 255, 241, 0.12), transparent 54%);
  mix-blend-mode: screen;
  opacity: 1;
  transition: opacity 0.6s ease;
}
.above .grade-water {
  opacity: 0;
}
.grade-grain {
  position: absolute;
  inset: -40%;
  opacity: 0.12;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.55'/%3E%3C/svg%3E");
  background-size: 180px 180px;
  mix-blend-mode: soft-light;
  animation: grainShift 0.8s steps(2) infinite;
}
@keyframes grainShift {
  0% { transform: translate3d(0, 0, 0); }
  25% { transform: translate3d(-2%, 1%, 0); }
  50% { transform: translate3d(1%, -2%, 0); }
  75% { transform: translate3d(2%, 2%, 0); }
  100% { transform: translate3d(-1%, -1%, 0); }
}
.grade-scan {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(180deg, transparent 0, transparent 3px, rgba(0, 0, 0, 0.045) 4px);
  opacity: 0.4;
  mix-blend-mode: multiply;
}

#damage-flash,
#surface-flash {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 7;
  opacity: 0;
}
#damage-flash {
  background: radial-gradient(ellipse at center, transparent 25%, rgba(168, 20, 10, 0.58) 100%);
  transition: opacity 0.3s ease;
}
#surface-flash {
